  if ((await srvSetting(env, "max_srv_seed_imo")) === sig) return;
  const rows = (await db.prepare("SELECT id, title, category, deleted FROM max_notes WHERE category LIKE 'Maritime%'").all().catch(() => ({results: []}))).results || [];
  const now = Date.now(), stmts = [], keys = []; let added = 0, updated = 0, kept = 0;
  for (const n of IMO_NOTES) {
    const key = "max_srv_seed_imo_" + n.id.replace(/[^a-z0-9]/gi, "_").slice(0, 40) + "_v" + n.v;
    if (await srvSetting(env, key)) continue;
    const same = rows.find(r => r.id === n.id) || rows.find(r => !r.deleted && String(r.title || "").trim().toLowerCase() === n.title.toLowerCase());
    if (same && same.deleted) { kept++; await srvSetting(env, key, "skipped: deleted by him"); continue; }
    const {v, ...note} = n, st = upsertNoteStmt(db, {...note, id: same ? same.id : n.id, createdAt: now, updatedAt: now});
    if (st) { stmts.push(st); keys.push(key); same ? updated++ : added++; }
  }
  for (let k = 0; k < stmts.length; k += 50) await db.batch(stmts.slice(k, k + 50));
  for (const key of keys) await srvSetting(env, key, String(now));
  await srvSetting(env, "max_srv_seed_imo", sig);
  if (added || updated) await logAct(env, {dept: "notes", kind: "organized notes", text: `IMO conventions and codes: added ${added} notes, updated ${updated}` + (kept ? `, left ${kept} you deleted` : "") + " (Maritime › IMO › Conventions / Codes, plus the IMO Index)", source: "Claude"});
