      if (ok.length || list.length) return ok.slice(0, 8).map(s => ({name: cleanText(s.name, 80), url: s.url_resolved, country: cleanText(s.countrycode || "", 4), tags: cleanText(s.tags || "", 80), bitrate: s.bitrate || 0}));
