      credit: cr, creditText: cr ? CREDIT_WORDS[cr] : null, earned: B ? Math.round(php - 100000 + (B.fees || 0)) : 0, paidOut: Math.round(B?.paidOut || 0), accrued: Math.round(B?.accrued || 0),
